#!/bin/bash

# Copyright (c) 2026 Relax Authors. All Rights Reserved.
#
# Qwen3.8-27B MTP-only draft training, 8xGPU single-node, ray-submit launch.
# The backbone, vision tower, projection, and LM head are frozen; only the
# native MTP block (the speculative-decoding draft) is optimized.
#
# The training set is a prompt/response JSONL. For a frozen target the
# responses should be generated by the target model itself, so the draft
# learns the distribution it has to agree with at verification time.
# Thinking-mode responses keep their leading "<think>\n...\n</think>\n\n" block.
#
# Usage:
#   MODEL_DIR=/path/to/models DATA_DIR=/path/to/data SAVE_DIR=/path/to/checkpoints \
#     bash scripts/training/sft/run-qwen38-27B-mtp-only-distill-8xgpu.sh

set -ex
set -o pipefail

now=$(date "+%Y%m%d-%H%M%S")
echo "Current time: $now"

: "${MODEL_DIR:?Set MODEL_DIR to the model root}"
: "${DATA_DIR:?Set DATA_DIR to the dataset root}"
: "${SAVE_DIR:?Set SAVE_DIR to a persistent checkpoint root}"

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" &>/dev/null && pwd)"
if [ -z "${RELAX_ENTRYPOINT_MODE:-}" ]; then
    source "${SCRIPT_DIR}/../../entrypoint/local.sh"
fi
source "${MODEL_CONFIG_DIR}/qwen38-27B.sh"

MTP_NUM_LAYERS="${MTP_NUM_LAYERS:-1}"
PROJECT_NAME="${PROJECT_NAME:-Relax/sft/mtp-draft}"
EXP_NAME="${EXP_NAME:-qwen38-27b-mtp-only-k${MTP_NUM_LAYERS}-distill-8xgpu}"

INIT_HF_DIR="${INIT_HF_DIR:-${MODEL_DIR}/Qwen3.8-27B}"
PROMPT_DATA="${PROMPT_DATA:-${DATA_DIR}/mtp-draft/qwen38-27B-distill-train.jsonl}"
RAY_ADDRESS="${RAY_ADDRESS:-http://${HOST_IP:-127.0.0.1}:8265}"
export RAY_NO_WAIT="${RAY_NO_WAIT-}"

CKPT_ARGS=(
   --hf-checkpoint "${INIT_HF_DIR}"
   --ref-load "${INIT_HF_DIR}"
   --megatron-to-hf-mode bridge
   --load "${SAVE_DIR}/${EXP_NAME}"
   --save "${SAVE_DIR}/${EXP_NAME}"
   --save-hf "${SAVE_DIR}/${EXP_NAME}-hf"
   --save-interval "${SAVE_INTERVAL:-200}"
   --max-actor-ckpt-to-keep "${MAX_ACTOR_CKPT_TO_KEEP:-1}"
   --num-epoch "${NUM_EPOCH:-2}"
)

SFT_ARGS=(
   --loss-type sft
   --prompt-data "${PROMPT_DATA}"
   --input-key prompt
   --label-key response
   --global-batch-size "${GLOBAL_BATCH_SIZE:-64}"
   --use-dynamic-batch-size
   --max-tokens-per-gpu "${MAX_TOKENS_PER_GPU:-20480}"
   --balance-data
)

MTP_ARGS=(
   --mtp-only-training
   --mtp-num-layers "${MTP_NUM_LAYERS}"
   --mtp-loss-scaling-factor "${MTP_LOSS_SCALING_FACTOR:-0.2}"
)
if [ "${MTP_NUM_LAYERS}" -gt 1 ]; then
   MTP_ARGS+=(
      --mtp-use-repeated-layer
   )
fi

PERF_ARGS=(
   --tensor-model-parallel-size 8
   --sequence-parallel
   --pipeline-model-parallel-size 1
   --context-parallel-size 1
   --expert-model-parallel-size 1
   --expert-tensor-parallel-size 1
   --calculate-per-token-loss
   --no-rope-fusion
   --cross-entropy-loss-fusion
)

OPTIMIZER_ARGS=(
   --optimizer adam
   --lr "${LR:-1e-5}"
   --lr-decay-style cosine
   --min-lr "${MIN_LR:-1e-6}"
   --weight-decay 0.1
   --adam-beta1 0.9
   --adam-beta2 0.98
   --clip-grad 1.0
)

WANDB_ARGS=(
   --use-clearml
   --use-metrics-service
   --use-tensorboard
   --tb-project-name "${PROJECT_NAME}"
   --tb-experiment-name "${EXP_NAME}-${now}"
)

MISC_ARGS=(
   --attention-dropout 0.0
   --hidden-dropout 0.0
   --accumulate-allreduce-grads-in-fp32
   --attention-softmax-in-fp32
   --attention-backend "${ATTENTION_BACKEND:-flash}"
   --use-health-check
)
if [ "${CI_TEST:-0}" = "1" ]; then
   MISC_ARGS+=(
      --ci-test
   )
fi

mkdir -p "${SCRIPT_DIR}/log"

ray job submit ${RAY_NO_WAIT:+--no-wait} --address="${RAY_ADDRESS}" \
   ${WORKING_DIR:+--working-dir "${WORKING_DIR}"} \
   --runtime-env-json="${RUNTIME_ENV_JSON}" \
   -- python3 -m relax.entrypoints.train \
   --resource '{"sft": [1, 0], "actor": [1, 8]}' \
   --sft-max-in-flight-steps 4 \
   --num-data-storage-units 8 \
   "${MODEL_ARGS[@]}" \
   "${CKPT_ARGS[@]}" \
   "${SFT_ARGS[@]}" \
   "${MTP_ARGS[@]}" \
   "${OPTIMIZER_ARGS[@]}" \
   "${WANDB_ARGS[@]}" \
   "${PERF_ARGS[@]}" \
   "${MISC_ARGS[@]}" 2>&1 | tee "${SCRIPT_DIR}/log/${EXP_NAME}-${now}.log"
